fn main() {
    let numbers = vec![1, 2, 3];
    let doubled = numbers.iter().map(|n| {
        println!("doubling {n}");
        n * 2
    });
    println!("nothing has been doubled yet");
    for d in doubled {
        println!("got {d}");
    }
}

fn main() {
    let result: Vec<i32> = (1..=10)
        .filter(|n| n % 2 == 0)   // keep 2, 4, 6, 8, 10
        .map(|n| n * n)           // square them
        .take(3)                  // stop after three
        .collect();
    println!("{:?}", result);
}

fn main() {
    let names = ["Ana", "Binh", "Chi"];
    let scores = [90, 75, 82];

    // enumerate pairs each item with its index, starting at 0
    for (i, name) in names.iter().enumerate() {
        println!("{i}: {name}");
    }

    // zip walks two iterators together and pairs their items up
    for (name, score) in names.iter().zip(scores.iter()) {
        println!("{name} scored {score}");
    }

    // chain joins one iterator after another; skip drops items from the front
    let joined: Vec<i32> = (1..=3).chain(10..=11).skip(1).collect();
    println!("{:?}", joined);

    // rev goes backwards
    for n in (1..=3).rev() {
        println!("countdown {n}");
    }
}

